using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SmokeBombEffect", menuName = "Data/Battle/Effects/Austra/SmokeBomb Effect")]
public class SmokeBombEffect : Effect
{
	[SerializeField]
	private int dodgePercentage;

	public int DodgePercentage => dodgePercentage;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = "";
		text = ((amount != EffectsValues.NO_VALUE && amount != -1) ? Smart.Format(GetLocalizedDescription(), dodgePercentage, amount) : GetEffectDescriptionWithAmountReplacedWithX(GetLocalizedDescription(), dodgePercentage, GetNumberToReplaceWithX()));
		return text + AppendedDescription();
	}
}
